contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(amount != 10);
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        bool reverted;
        c.play{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.pot() == potBefore && address(c).balance == balBefore);
    }
    receive() external payable {}
}

